authorizationControl.initialAuthorizationCheck:
if (current::actionId == 'execute') { 
    if (current::resourceId === '/afw/_AdaptiveFunction_/service_get') 
        return { 'decisionId': 'permit' }; 
    else if (current::resourceId == '/afw/_AdaptiveFunction_/service_restart') {
        const funcObj = current::object;
        assert(funcObj.function.functionLabel === 'service_restart');

	if (length(funcObj.arguments) === 1)
            assert(funcObj.arguments[0] === 'adapter-files');

        else if (length(funcObj.arguments) === 2) {
            assert(funcObj.arguments[0] === 'adapter-files');
            assert(funcObj.arguments[1] === 42);
        }

        return { 'decisionId': 'permit' }; 
    }
} else {
    return {'decisionId': 'permit'};
}
